#include "shell/surface_lifecycle.hpp"
#include "support/check.hpp"
int main(){namespace t=squiflow::testing;using namespace squiflow::shell;using namespace squiflow::app;t::section("ordered surface startup");int requests=0;SurfaceLifecycle s([&](auto reason){if(reason==ShutdownReason::WindowClosed)++requests;});t::check(s.start_window(true).disposition==StepDisposition::Failed,"window cannot precede shell");SurfaceLifecycle good([&](auto){++requests;});t::check(good.start_shell(true).disposition==StepDisposition::Started,"shell starts at step 11");t::check(good.start_window(true).disposition==StepDisposition::Started,"window starts at step 12");good.request_shutdown();good.request_shutdown();t::check(requests==1,"close intent is idempotent");good.stop_window();good.stop_shell();t::check(good.state()==SurfaceState::Stopped,"reverse unwind closes window then shell");t::section("creation failures");SurfaceLifecycle bad({});auto failure=bad.start_shell(false,std::string(700,'x'));t::check(failure.disposition==StepDisposition::Failed&&failure.message.size()==kMaxLifecycleDiagnostic,"engine failure is bounded");bad.stop_shell();t::check(bad.state()==SurfaceState::Stopped,"failed shell unwinds");return t::report();}
